  const scale = 1 / volume.radius;
  const row = (axis, sign) => [axis[0] * scale * sign, axis[1] * scale * sign, axis[2] * scale * sign, -sign * (axis[0] * cx + axis[1] * cy + axis[2] * cz) * scale];
