/* ------------------------------------------------------------------------ */
/* Regional skin variation                                                  */
/* ------------------------------------------------------------------------ */

function srgbChannelToLinear(value) { return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4; }

