function normalize(a, fallback = [0, 0, 1]) { const l = lengthOf(a); return l > 1e-12 ? [a[0] / l, a[1] / l, a[2] / l] : [...fallback]; }
function lerp3(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
