    const [innerLandmark, outerLandmark] = side < 0 ? [39, 36] : [42, 45];
    const near = (vertex) => lengthOf(sub(point(template, vertex), frame.center)) < 0.03;
    const socket = (vertex) => field("eyeSocket", vertex) >= 0.5;
