      innerLandmark,
      outerLandmark,
      sclera: eye.sclera,
      pupil: eye.pupil,
      iris: eye.iris,
      limbus: eye.limbus,
      dome: eye.dome,
      spokeCount: count,
      spokes,
      innerSpoke,
      outerSpoke,
